def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c

    # Very short history: default cooperate
    if n < 8:
        return 'C'

    # Identify likely pure-defector
    if n >= 10:
        last10 = opp[-10:]
        d10 = last10.count('D')
        if d10 >= 9:
            return 'D'
        # Identified pure-cooperator: exploit with periodic defect
        if d10 == 0:
            if n == 50 or n == 75 or (n > 20 and n % 22 == 0):
                return 'D'
            return 'C'

    # Consecutive defection detection
    if n >= 3 and opp[-1] == 'D' and opp[-2] == 'D' and opp[-3] == 'D':
        # Three in a row: punish but occasionally test re-establish
        if n >= 6 and opp[-4] == 'D' and opp[-5] == 'D':
            # Long defection: exploit occasional cooperate
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        return 'D'

    last_opp = opp[-1]
    last_me = me[-1]

    # Two consecutive defections
    if last_opp == 'D' and n >= 2 and opp[-2] == 'D':
        return 'D'

    # Opponent just defected (isolated)
    if last_opp == 'D':
        # If we cooperated and got exploited, definitely punish
        if last_me == 'C':
            return 'D'
        # Both defected (DD). Try to restore cooperation with modest prob.
        # Count consecutive DD
        dd_run = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'D' and opp[i] == 'D':
                dd_run += 1
            else:
                break
        if dd_run >= 2:
            # Long DD streak: try to break with small prob
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        # First DD
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent just cooperated
    if last_me == 'D':
        # We may have been retaliating. Return to cooperation unless opponent weak.
        # Check recent defection rate of opponent
        recent = opp[-8:]
        recent_d = recent.count('D')
        if recent_d >= 4:
            # Opponent still defecting a lot: keep punishing
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'C'

    # Both cooperated last round
    # Endgame: defect in last few rounds (shadow ends)
    rounds_left = 100 - n
    if rounds_left <= 2:
        return 'D'
    if rounds_left <= 4:
        # If opponent has shown willingness to defect, defect now
        recent = opp[-6:]
        if recent.count('D') >= 1:
            return 'D'
        return 'C'

    # Late game: if opponent very cooperative all game, defect periodically
    if n >= 85:
        recent = opp[-15:]
        if recent.count('C') >= 14:
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        if recent.count('D') >= 3:
            return 'D'
        return 'C'

    # Mid-game: track opponent cooperation rate
    if opp_d == 0:
        # Perfect cooperator: occasional exploit
        if n >= 20 and rng.random() < 0.08:
            return 'D'
        return 'C'

    if opp_c * 3 >= n * 2:
        # Mostly cooperative
        # Occasional test defection
        if n >= 15 and rng.random() < 0.06:
            return 'D'
        return 'C'

    if opp_d * 2 > n:
        # Mostly defective: defect, occasionally cooperate to test
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Mixed opponent: tit-for-tat with forgiveness
    # If we've been in mutual cooperation recently, continue
    recent5 = opp[-5:]
    if recent5.count('C') >= 4:
        return 'C'
    if recent5.count('D') >= 3:
        return 'D'
    return 'C'
